import { open, Database } from 'node:sqlite';
import { sqlite3 } from 'node:sqlite';

let db: Database;

export async function initDB() {
  db = await open({
    filename: './tasks.db',
    driver: sqlite3.Database
  });

  await db.exec(`
    CREATE TABLE IF NOT EXISTS tasks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      title TEXT NOT NULL,
      description TEXT,
      completed INTEGER DEFAULT 0
    )
  `);
}

export async function createTask(title: string, description: string) {
  await db.run('INSERT INTO tasks (title, description) VALUES (?, ?)', [title, description]);
  return await db.get('SELECT last_insert_rowid() as id');
}

export async function getTasks(filter: 'all' | 'active' | 'completed' = 'all') {
  let query = 'SELECT * FROM tasks';
  if (filter === 'active') {
    query += ' WHERE completed = 0';
  } else if (filter === 'completed') {
    query += ' WHERE completed = 1';
  }
  query += ' ORDER BY id DESC';
  return await db.all(query);
}

export async function getTaskById(id: number) {
  return await db.get('SELECT * FROM tasks WHERE id = ?', [id]);
}

export async function updateTask(id: number, title: string, description: string) {
  await db.run('UPDATE tasks SET title = ?, description = ? WHERE id = ?', [title, description, id]);
  return await getTaskById(id);
}

export async function deleteTask(id: number) {
  await db.run('DELETE FROM tasks WHERE id = ?', [id]);
}

export async function completeTask(id: number) {
  await db.run('UPDATE tasks SET completed = 1 WHERE id = ?', [id]);
  return await getTaskById(id);
}

document.addEventListener('DOMContentLoaded', () => {
  const taskForm = document.getElementById('taskForm');
  const taskContainer = document.getElementById('taskContainer');
  const filterButtons = document.querySelectorAll('.filter');

  let currentFilter = 'all';

  // Fetch tasks from the API
  const fetchTasks = async () => {
    try {
      const response = await fetch('/api/tasks');
      const tasks = await response.json();
      renderTasks(tasks);
    } catch (error) {
      console.error('Error fetching tasks:', error);
    }
  };

  // Render tasks based on current filter
  const renderTasks = (tasks) => {
    let filteredTasks = tasks;

    if (currentFilter === 'active') {
      filteredTasks = tasks.filter(task => !task.completed);
    } else if (currentFilter === 'completed') {
      filteredTasks = tasks.filter(task => task.completed);
    }

    taskContainer.innerHTML = '';

    if (filteredTasks.length === 0) {
      taskContainer.innerHTML = '<p>No tasks found.</p>';
      return;
    }

    filteredTasks.forEach(task => {
      const taskElement = document.createElement('div');
      taskElement.className = `task ${task.completed ? 'completed' : ''}`;
      taskElement.innerHTML = `
        <div class="task-content">
          <h3>${task.title}</h3>
          <p>${task.description}</p>
        </div>
        <div class="task-actions">
          <button class="edit-btn" data-id="${task.id}">Edit</button>
          <button class="toggle-btn" data-id="${task.id}">${task.completed ? 'Active' : 'Complete'}</button>
          <button class="delete-btn" data-id="${task.id}">Delete</button>
        </div>
      `;
      taskContainer.appendChild(taskElement);
    });

    // Add event listeners to task buttons
    document.querySelectorAll('.edit-btn').forEach(btn => {
      btn.addEventListener('click', handleEditTask);
    });

    document.querySelectorAll('.toggle-btn').forEach(btn => {
      btn.addEventListener('click', handleToggleTask);
    });

    document.querySelectorAll('.delete-btn').forEach(btn => {
      btn.addEventListener('click', handleDeleteTask);
    });
  };

  // Handle form submission
  taskForm.addEventListener('submit', async (e) => {
    e.preventDefault();

    const title = document.getElementById('title').value.trim();
    const description = document.getElementById('description').value.trim();

    if (!title) return;

    try {
      const response = await fetch('/api/tasks', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ title, description })
      });

      if (response.ok) {
        taskForm.reset();
        fetchTasks();
      } else {
        console.error('Error creating task');
      }
    } catch (error) {
      console.error('Error creating task:', error);
    }
  });

  // Handle edit task
  const handleEditTask = async (e) => {
    const id = e.target.dataset.id;

    try {
      const response = await fetch(`/api/tasks/${id}`);
      const task = await response.json();

      // Fill form with task data
      document.getElementById('title').value = task.title;
      document.getElementById('description').value = task.description;

      // Change form button to update
      const submitBtn = taskForm.querySelector('button[type="submit"]');
      submitBtn.textContent = 'Update Task';

      // Store task ID for update
      taskForm.dataset.taskId = id;

      // Change form submit handler
      taskForm.onsubmit = async (e) => {
        e.preventDefault();

        const title = document.getElementById('title').value.trim();
        const description = document.getElementById('description').value.trim();

        if (!title) return;

        try {
          const updateResponse = await fetch(`/api/tasks/${id}`, {
            method: 'PUT',
            headers: {
              'Content-Type': 'application/json'
            },
            body: JSON.stringify({ title, description })
          });

          if (updateResponse.ok) {
            taskForm.reset();
            submitBtn.textContent = 'Add Task';
            delete taskForm.dataset.taskId;
            taskForm.onsubmit = null;
            fetchTasks();
          } else {
            console.error('Error updating task');
          }
        } catch (error) {
          console.error('Error updating task:', error);
        }
      };
    } catch (error) {
      console.error('Error fetching task for edit:', error);
    }
  };

  // Handle toggle task completion
  const handleToggleTask = async (e) => {
    const id = e.target.dataset.id;

    try {
      // First get the task to get current completion status
      const response = await fetch(`/api/tasks/${id}`);
      const task = await response.json();

      // Toggle completion status
      const completed = !task.completed;

      const updateResponse = await fetch(`/api/tasks/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ completed })
      });

      if (updateResponse.ok) {
        fetchTasks();
      } else {
        console.error('Error toggling task completion');
      }
    } catch (error) {
      console.error('Error toggling task completion:', error);
    }
  };

  // Handle delete task
  const handleDeleteTask = async (e) => {
    const id = e.target.dataset.id;

    if (!confirm('Are you sure you want to delete this task?')) return;

    try {
      const response = await fetch(`/api/tasks/${id}`, {
        method: 'DELETE'
      });

      if (response.ok) {
        fetchTasks();
      } else {
        console.error('Error deleting task');
      }
    } catch (error) {
      console.error('Error deleting task:', error);
    }
  };

  // Handle filter buttons
  filterButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      // Update active filter
      filterButtons.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      currentFilter = btn.dataset.filter;

      // Re-render tasks
      fetchTasks();
    });
  });

  // Initial fetch
  fetchTasks();
});

import { open } from 'node:sqlite';
import { sqlite3 } from 'node:sqlite';

// Create or open the database
const openDb = async () => {
  return await open({
    filename: './tasks.db',
    driver: sqlite3.Database
  });
};

// Create a new task
export const createTask = async (title, description) => {
  const db = await openDb();
  const result = await db.run(
    'INSERT INTO tasks (title, description) VALUES (?, ?)',
    [title, description]
  );
  return await db.get('SELECT * FROM tasks WHERE id = ?', [result.lastID]);
};

// Get all tasks
export const getTasks = async () => {
  const db = await openDb();
  return await db.all('SELECT * FROM tasks');
};

// Get a task by ID
export const getTaskById = async (id) => {
  const db = await openDb();
  return await db.get('SELECT * FROM tasks WHERE id = ?', [id]);
};

// Update a task
export const updateTask = async (id, title, description, completed) => {
  const db = await openDb();
  const result = await db.run(
    'UPDATE tasks SET title = ?, description = ?, completed = ? WHERE id = ?',
    [title, description, completed ? 1 : 0, id]
  );

  if (result.changes === 0) {
    return null;
  }

  return await db.get('SELECT * FROM tasks WHERE id = ?', [id]);
};

// Delete a task
export const deleteTask = async (id) => {
  const db = await openDb();
  const result = await db.run('DELETE FROM tasks WHERE id = ?', [id]);
  return result.changes > 0;
};

import { createServer } from 'http';
import { open } from 'node:sqlite';
import { sqlite3 } from 'node:sqlite';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const dbFile = join(__dirname, 'tasks.db');
let db;

const server = createServer(async (req, res) => {
  // Handle API routes
  if (req.url.startsWith('/api/')) {
    handleAPI(req, res);
    return;
  }

  // Serve static files
  if (req.url === '/' || req.url === '/index.html') {
    serveFile(res, join(__dirname, 'index.html'), 'text/html');
    return;
  }

  if (req.url === '/app.js') {
    serveFile(res, join(__dirname, 'app.js'), 'application/javascript');
    return;
  }

  if (req.url === '/style.css') {
    serveFile(res, join(__dirname, 'style.css'), 'text/css');
    return;
  }

  // 404 for other routes
  res.writeHead(404, { 'Content-Type': 'text/plain' });
  res.end('Not Found');
});

async function handleAPI(req, res) {
  if (!db) {
    db = await open({
      filename: dbFile,
      driver: sqlite3.Database
    });

    // Create tasks table if not exists
    await db.exec(`
      CREATE TABLE IF NOT EXISTS tasks (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT NOT NULL,
        description TEXT,
        completed INTEGER DEFAULT 0
      )
    `);
  }

  // Set CORS headers
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'GET' && req.url === '/api/tasks') {
    try {
      const tasks = await db.all('SELECT * FROM tasks');
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(tasks));
    } catch (error) {
      res.writeHead(500, { 'Content-Type': 'text/plain' });
      res.end('Server error');
    }
    return;
  }

  if (req.method === 'POST' && req.url === '/api/tasks') {
    let body = '';
    req.on('data', chunk => {
      body += chunk.toString();
    });
    req.on('end', async () => {
      try {
        const { title, description } = JSON.parse(body);
        if (!title) {
          res.writeHead(400, { 'Content-Type': 'text/plain' });
          res.end('Title is required');
          return;
        }

        const result = await db.run(
          'INSERT INTO tasks (title, description) VALUES (?, ?)',
          [title, description]
        );

        const newTask = await db.get('SELECT * FROM tasks WHERE id = ?', [result.lastID]);
        res.writeHead(201, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(newTask));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'text/plain' });
        res.end('Server error');
      }
    });
    return;
  }

  if (req.method === 'PUT' && req.url.match(/\/api\/tasks\/(\d+)/)) {
    const id = req.url.match(/\/api\/tasks\/(\d+)/)[1];
    let body = '';
    req.on('data', chunk => {
      body += chunk.toString();
    });
    req.on('end', async () => {
      try {
        const { title, description, completed } = JSON.parse(body);

        const result = await db.run(
          'UPDATE tasks SET title = ?, description = ?, completed = ? WHERE id = ?',
          [title, description, completed ? 1 : 0, id]
        );

        if (result.changes === 0) {
          res.writeHead(404, { 'Content-Type': 'text/plain' });
          res.end('Task not found');
          return;
        }

        const updatedTask = await db.get('SELECT * FROM tasks WHERE id = ?', [id]);
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(updatedTask));
      } catch (error) {
        res.writeHead(500, { 'Content-Type': 'text/plain' });
        res.end('Server error');
      }
    });
    return;
  }

  if (req.method === 'DELETE' && req.url.match(/\/api\/tasks\/(\d+)/)) {
    const id = req.url.match(/\/api\/tasks\/(\d+)/)[1];
    try {
      const result = await db.run('DELETE FROM tasks WHERE id = ?', [id]);

      if (result.changes === 0) {
        res.writeHead(404, { 'Content-Type': 'text/plain' });
        res.end('Task not found');
        return;
      }

      res.writeHead(204, { 'Content-Type': 'text/plain' });
      res.end();
    } catch (error) {
      res.writeHead(500, { 'Content-Type': 'text/plain' });
      res.end('Server error');
    }
    return;
  }

  res.writeHead(404, { 'Content-Type': 'text/plain' });
  res.end('Not Found');
}

function serveFile(res, filePath, contentType) {
  const fs = require('fs');
  fs.readFile(filePath, (err, data) => {
    if (err) {
      res.writeHead(500, { 'Content-Type': 'text/plain' });
      res.end('Server error');
      return;
    }
    res.writeHead(200, { 'Content-Type': contentType });
    res.end(data);
  });
}

